const lessons=[{"sentences":[{"speaker":"A","text":"Excuse me do you know where we keep the new desk labels for the open plan office.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.159625},{"speaker":"B","text":"They arrived this morning and are sitting inside the supply cupboard near the main printer.","position":2,"audioStartSeconds":5.359625,"audioEndSeconds":10.480583333333334},{"speaker":"A","text":"I checked there earlier but only found old folders and boxes of printer paper.","position":3,"audioStartSeconds":10.680583333333333,"audioEndSeconds":15.720041666666667},{"speaker":"B","text":"Perhaps Sarah moved them because she is leading the seating arrangement project this week.","position":4,"audioStartSeconds":15.920041666666666,"audioEndSeconds":21.127},{"speaker":"A","text":"Let me send her a quick message before we start printing our staff names.","position":5,"audioStartSeconds":21.327,"audioEndSeconds":26.056375},{"speaker":"B","text":"She should reply quickly since she is sitting right at her corner desk today.","position":6,"audioStartSeconds":26.256375,"audioEndSeconds":30.921333333333333},{"speaker":"A","text":"Great because we need everything labeled before the new marketing team arrives tomorrow morning.","position":7,"audioStartSeconds":31.121333333333332,"audioEndSeconds":36.63679166666667},{"section-start":true,"speaker":"A","text":"Hi Mark we need to arrange transport for the heavy audio equipment to the conference center.","role":"section-start","position":8,"audioStartSeconds":41.63679166666667,"audioEndSeconds":47.38420833333333},{"speaker":"B","text":"Can we just use our usual delivery van parked behind the main office building.","position":9,"audioStartSeconds":47.584208333333336,"audioEndSeconds":52.648666666666664},{"speaker":"A","text":"Unfortunately that vehicle is scheduled for routine maintenance all day throughout tomorrow.","position":10,"audioStartSeconds":52.84866666666667,"audioEndSeconds":58.196625},{"speaker":"B","text":"We could rent a small truck from the local transport agency down the street.","position":11,"audioStartSeconds":58.396625,"audioEndSeconds":63.113083333333336},{"speaker":"A","text":"That sounds expensive since management requested we keep expenses under fifty dollars.","position":12,"audioStartSeconds":63.31308333333333,"audioEndSeconds":69.12491666666666},{"speaker":"B","text":"My colleague has a large trailer attached to his car and might help us move it.","position":13,"audioStartSeconds":69.32491666666667,"audioEndSeconds":74.09295833333333},{"speaker":"A","text":"That is a brilliant idea because it costs nothing and fits all our gear safely.","position":14,"audioStartSeconds":74.29295833333333,"audioEndSeconds":79.559375},{"speaker":"B","text":"I will call him right now to confirm if he is available this afternoon.","position":15,"audioStartSeconds":79.759375,"audioEndSeconds":84.36583333333333}],"questions":[{"prompt":"What are the speakers trying to find?","options":["New desk labels.","Printer paper.","Old folders."],"answer":"A","evidenceSentence":1,"evidence":"new desk labels","explanation":"Người nói A hỏi về vị trí của các nhãn dán bàn mới cho văn phòng."},{"prompt":"Where did speaker B think the items were initially?","options":["In the storage room.","Inside the supply cupboard.","On the corner desk."],"answer":"B","evidenceSentence":2,"evidence":"sitting inside the supply cupboard","explanation":"Người nói B ban đầu nghĩ rằng chúng nằm trong tủ vật tư gần máy in."},{"prompt":"Why do they need the items urgently?","options":["The printer is broken.","Sarah requested them.","New marketing staff arrive tomorrow."],"answer":"C","evidenceSentence":7,"evidence":"new marketing team arrives tomorrow morning","explanation":"Họ cần hoàn thành việc dán nhãn trước khi đội ngũ marketing mới đến vào sáng mai."},{"prompt":"What equipment needs to be moved in the second conversation?","options":["Heavy audio equipment.","Office printers.","Marketing documents."],"answer":"A","evidenceSentence":8,"evidence":"heavy audio equipment","explanation":"Họ cần vận chuyển thiết bị âm thanh nặng đến trung tâm hội nghị."},{"prompt":"Why can they not use the usual delivery van?","options":["It is being repaired.","It is too small.","It costs too much."],"answer":"A","evidenceSentence":10,"evidence":"scheduled for routine maintenance","explanation":"Xe tải thông thường đang được bảo trì định kỳ vào ngày mai."},{"prompt":"What solution do they finally agree upon?","options":["Renting a small truck.","Using a colleague's trailer.","Canceling the conference."],"answer":"B","evidenceSentence":13,"evidence":"large trailer attached to his car","explanation":"Họ đồng ý sử dụng chiếc moóc gắn liền với xe hơi của đồng nghiệp để tiết kiệm chi phí."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
